wire[3:0] ef;wire[191:0] high,low,setup,hold;wire[383:0] rates;
wire stop,mreq,oreq,permit,pm,po,consumed,accepted,effective,io;wire[1:0] tests;wire[2:0] teststate;
wire signed[31:0] counts[0:11];
wire[3:0] gates={4{mreq&&inhibit}};
cnc3_command_validate validate(frame,frame[1367:1360]==6,frame[1367:1360]==6?9'd176:9'd96,1'b1,1'b1,structural);
reg admission_start=0,admission_word_valid=0;reg[3:0] admission_channel=0;reg[31:0] admission_rate=0;
wire admission_good,admission_busy,admission_poisoned;wire[11:0] admission_channels;
cnc3_rate_admission_serial actual_admission(clk,rst,admission_start,admission_word_valid,admission_channel,admission_rate,high,low,admission_good,admission_busy,admission_poisoned,admission_channels);
cnc3_motion_state d(.clk(clk),.rst_n(rst),.request_valid(rv),.request_frame(frame),.reject_pulse(reject),.rejected_configure(rejectedcfg),.request_rates_valid(admission_good),.qualification_complete(qual),.installed_input(installed),.installed_module_class(moduleclass),.inhibit_n(inhibit),.wd_m_ok(wm),.wd_o_ok(wo),.reset_arm_ready(ready),.reset_arm_held(held),.contactor_deenergized(contactor),.sto_arm_expected(sto),.motion_critical_ports_valid(ports),.encoder_valid_mask(ev),.encoder_installed_mask(ei),.encoder_expansion_class(8'd0),.alarm_levels(alarms),.timing_faults(timing),.external_fault_word(extfault),.motion_critical_io_fault(criticalio),.gate_high(gates),.opi_ok(opi),.generator_quiescent(quiet),.request_ready(),.session(sess),.last_sequence(seq),.ticks(tick),.fault_word(fw),.installed_mask(im),.required_mask(rm),.armed_mask(am),.pos_continuity(continuity),.step_timing_latched(st),.alarm_trip_latched(al),.config_valid(cfgv),.config_generation(gen),.config_hash(chash),.config_crc(ccrc),.servo_period_us(servo),.required_encoder_mask(rem),.encoder_filter_ticks(ef),.mpg_config(mpg),.pulse_ticks(high),.space_ticks(low),.setup_ticks(setup),.hold_ticks(hold),.rates(rates),.generator_enable(enable),.generator_stop(stop),.motion_request(mreq),.output_request(oreq),.permit_out_req(permit),.progress_m(pm),.progress_o(po),.opi_rearm(rearm),.reset_arm_consumed(consumed),.selftest_passed(tests),.selftest_state(teststate),.accepted_pulse(accepted),.last_reject(lastrej),.last_update_interval_us(interval),.late_update_count(late),.motion_effective(effective),.state_bits(state),.io_enabled(io));
genvar k;generate for(k=0;k<12;k=k+1)begin:g
cnc3_stepgen_runtime sg(clk,rst,enable[k],stop,$signed(rates[383-32*k -:32]),high[191-16*k -:16],low[191-16*k -:16],setup[191-16*k -:16],hold[191-16*k -:16],steps[k],dirs[k],counts[k],timing[k],quiet[k]);
end endgenerate
always@(posedge clk)if(autoopi)begin
if(!mreq || !inhibit)opi<=0;else opi<=opi|rearm;
end
integer checks=0,j,elapsed;reg[11:0] savedcontinuity;reg signed[31:0] savedcounts[0:11];
task check(input bit yes,input string message);begin checks=checks+1;if(!yes)$fatal(1,"%s tick%0d fault%h",message,tick,fw);end endtask
task ticks(input integer n);begin repeat(n)@(negedge clk);end endtask
task scan_admission(input[1407:0] value);
integer c;begin
@(negedge clk);admission_start=1;admission_word_valid=0;@(negedge clk);admission_start=0;
for(c=0;c<12;c=c+1)begin admission_channel=c[3:0];admission_rate=value[1279-32*c -:32];admission_word_valid=1;
@(negedge clk);admission_word_valid=0;ticks(12);end
end endtask
 task send(input[1407:0] value);begin
@(negedge clk);frame=value;#1;
// FB_READ also uses CS_FB. This bench's static checker chip-select is corrected
// explicitly for the two readonly frame classes used here.
if(value[1367:1360]!=16)check(structural==0,"actual frozen static frame acceptance");
if(value[1367:1360]==3)scan_admission(value);
rv=1;@(negedge clk);rv=0;#1;
end endtask
task send_at_delta(input[1407:0] value,input integer delta);begin
frame=value;scan_admission(value);
while(tick-d.last_update_tick<delta)@(negedge clk);#1;check(structural==0,"late interval real static validation");rv=1;
@(negedge clk);rv=0;#1;
end endtask
task cold;begin rst=0;rv=0;wm=1;wo=1;qual=0;inhibit=1;autoopi=1;opi=0;installed=12'hfff;held=0;ready=1;ports=1;extfault=0;ticks(4);rst=1;ticks(2);qual=1;ticks(3);end endtask
task test_watchdog(input bit output_test);begin
send(output_test?testo:testm);
check(teststate==(output_test?3:1),"real selftest start");
for(elapsed=0;elapsed<500000;elapsed=elapsed+1)begin
ticks(1);
if(elapsed%4096==0)begin
check(enable==0 && steps==0 && dirs==0 && permit==0 && pm==0 && po==0 && rates==0 && io==0,"selftest containment");
check(output_test?(oreq&&!mreq):(mreq&&!oreq),"only selected watchdog request");
end
end
check(output_test?!tests[1]:!tests[0],"no instant SELFTEST flag");
if(output_test)wo=0;else wm=0;ticks(2);
check(teststate==(output_test?4:2),"measured fall enters recovery wait");
check(output_test?tests[1]:tests[0],"only observed timely fall passed");
check(!mreq&&!oreq,"selftest request low after fall");
ticks(200);check(teststate!=(0),"must wait actual WDO recovery");
if(output_test)wo=1;else wm=1;ticks(3);check(teststate==0,"recovery observed");
end endtask

reg[31:0] hostsession=32'h55667788,sessioncounter=32'h90000000,hostseq=2;
reg[1407:0] workframe;integer profile,channel,cases=0;reg[31:0] cap;
function[1407:0] reseal(input[1407:0] raw,input bit usefb);
reg[15:0] crc;reg[1407:0] copy;integer b,body;begin
crc=16'hffff;body=usefb?1392:752;
for(b=0;b<body;b=b+1)begin
if(crc[15]^raw[1407-b])crc={crc[14:0],1'b0}^16'h1021;else crc={crc[14:0],1'b0};end
copy=raw;if(usefb)copy[15:0]=crc;else copy[655:640]=crc;reseal=copy;end endfunction
task config_profile(input[1407:0] raw);
begin workframe=raw;workframe[1343 -:32]=hostsession;workframe[1311 -:32]=hostsession?hostseq+1:0;
send(reseal(workframe,1));check(cfgv&&sess==0,"valid timing profile commits atomically");hostsession=0;hostseq=0;end endtask
task begin_case;
begin sessioncounter=sessioncounter+1;hostsession=sessioncounter;
workframe=sync2;workframe[1343 -:32]=hostsession;send(reseal(workframe,0));check(fw==0,"explicit new SYNC before independent case");
workframe=arm;workframe[1343 -:32]=hostsession;workframe[1311 -:32]=1;send(reseal(workframe,0));hostseq=1;ticks(8);
check(am==12'hfff&&enable==12'hfff,"real observed ARM for admission case");end endtask
task rate_case(input[31:0] value,input integer selected,input bit allowed);
begin begin_case();workframe=update;workframe[1343 -:32]=hostsession;workframe[1311 -:32]=2;workframe[1279 -:384]=0;
if(selected==12)begin for(j=0;j<12;j=j+1)workframe[1279-32*j -:32]=j%2?-value:value;end
else workframe[1279-32*selected -:32]=value;
workframe=reseal(workframe,0);send(workframe);cases=cases+1;
if(allowed)begin
check(am==12'hfff&&seq==2&&accepted&&rates==workframe[1279 -:384]&&pm,"valid host rate admitted atomically");hostseq=2;
workframe=disarm;workframe[1343 -:32]=hostsession;workframe[1311 -:32]=3;send(reseal(workframe,0));hostseq=3;ticks(2300);
check(am==0&&!mreq&&!fw[3],"actual clean no-timing-fault stop");
end else begin
check(am==0&&seq==1&&!accepted&&rates==0&&!pm&&fw[0]&&cfgv,"bad rate rejected atomically before admission");
check(enable==0&&!permit,"bad rate never receives actuator authority");end
end endtask
initial begin
cold();send(cfg);send(sync2);test_watchdog(0);test_watchdog(1);
for(profile=0;profile<5;profile=profile+1)begin
case(profile)
0:begin config_profile(profile0);cap=32'd16777216;end
1:begin config_profile(profile1);cap=32'd16777216;end
2:begin config_profile(profile2);cap=32'd2098176;end
3:begin config_profile(profile3);cap=32'd4286394;end
4:begin config_profile(profile4);cap=32'd3821145;end
endcase
rate_case(cap,12,1);
for(channel=0;channel<12;channel=channel+1)begin
rate_case(cap,channel,1);rate_case(-cap,channel,1);
rate_case(cap+1,channel,0);rate_case(-(cap+1),channel,0);
rate_case(32'h80000000,channel,0);rate_case(0,channel,1);
end
end
$display("RATE_ADMISSION_PASS checks=%0d actual_cases=%0d actual_generators=12",checks,cases);$finish;
end
